// Construye el mensaje tal como lo publicaría un lector RFID industrial (formato tipo Zebra FX).
const reads = msg.reads || [{ readerId: msg.readerId, epc: msg.epc }];
const out = [];
for (const r of reads) {
  const burst = r.burst || 1; // los lectores reales reportan la misma etiqueta varias veces
  for (let i = 0; i < burst; i++) {
    out.push({
      topic: `bibliotheca/readers/${r.readerId}/tags`,
      payload: {
        type: 'SIMPLE',
        timestamp: new Date().toISOString(),
        data: { idHex: r.epc, antenna: 1 + Math.floor(Math.random() * 2), peakRssi: -40 - Math.floor(Math.random() * 25) }
      }
    });
  }
}
node.status({ fill: 'blue', shape: 'dot', text: `${out.length} lecturas publicadas` });
return [out];

// Inventario automático: cada estante inteligente reporta las etiquetas que tiene encima.
// Copias por libro y estante según los datos semilla de catalog-service.
const copies = [3,2,3,2,2,1,2,2,2,3,3,2,3,2,2,2,2,1,2,2,2,3,2,1,1,3,2,2,2,1,2,2];
const shelfOf = (i) => (i <= 12 || i === 32) ? 'SHELF-A' : (i <= 18 ? 'SHELF-B' : (i <= 25 ? 'SHELF-C' : 'SHELF-D'));
const onLoan = flow.get('onLoan') || ['E00401500000012D', 'E004015000000515'];
const epc = (i, j) => 'E0040150' + (i * 100 + j).toString(16).toUpperCase().padStart(8, '0');
const reads = [];
copies.forEach((n, idx) => {
  const i = idx + 1;
  for (let j = 1; j <= n; j++) {
    const tag = epc(i, j);
    if (onLoan.includes(tag)) continue;     // los libros prestados no están en el estante
    if (Math.random() < 0.03) continue;     // simulamos lecturas perdidas (~3 %)
    reads.push({ readerId: shelfOf(i), epc: tag });
  }
});
msg.reads = reads;
return msg;

// Latido de cada lector físico (estado en línea / fuera de línea en la app).
const readers = ['GATE-01', 'DESK-01', 'RETURN-01', 'SHELF-A', 'SHELF-B', 'SHELF-C', 'SHELF-D'];
return [readers.map((id) => ({ topic: `bibliotheca/readers/${id}/heartbeat`, payload: { readerId: id, ts: new Date().toISOString(), firmware: '2.4.1' } }))];

// POST http://localhost:1880/simular  { "readerId": "GATE-01", "epc": "E004015000000065", "burst": 3 }
const b = msg.payload || {};
if (!b.readerId || !b.epc) { msg.statusCode = 400; msg.payload = { error: 'readerId y epc son obligatorios' }; return [null, msg]; }
msg.reads = [{ readerId: String(b.readerId).toUpperCase(), epc: String(b.epc).toUpperCase(), burst: Number(b.burst) || 1 }];
const ok = { payload: { ok: true, published: msg.reads }, req: msg.req, res: msg.res };
return [msg, ok];

// bibliotheca/readers/<readerId>/tags → lectura normalizada
const readerId = (msg.topic || '').split('/')[2];
const p = msg.payload || {};
const data = p.data || p;
const epc = String(data.idHex || data.epc || '').replace(/[\s:-]/g, '').toUpperCase();
if (!readerId || !/^[0-9A-F]{8,32}$/.test(epc)) {
  node.warn(`Lectura descartada (${msg.topic}): ${JSON.stringify(p)}`);
  return null;
}
msg.payload = { readerId, epc, rssi: data.peakRssi ?? data.rssi ?? null, antenna: data.antenna ?? null, timestamp: p.timestamp || new Date().toISOString() };
return msg;

// Agrupa lecturas por lector y envía un lote por segundo (reduce llamadas HTTP).
const buffer = context.get('buffer') || {};
const r = msg.payload;
(buffer[r.readerId] = buffer[r.readerId] || []).push({ epc: r.epc, rssi: r.rssi, antenna: r.antenna, timestamp: r.timestamp });
context.set('buffer', buffer);
if (!context.get('timer')) {
  context.set('timer', setTimeout(() => {
    const pending = context.get('buffer') || {};
    context.set('buffer', {});
    context.set('timer', null);
    for (const [readerId, reads] of Object.entries(pending)) {
      node.send({ readerId, payload: { readerId, reads } });
    }
  }, 1000));
}
return null;

msg.method = 'POST';
msg.url = (env.get('RFID_SERVICE_URL') || 'http://rfid-service:3004') + '/internal/rfid/ingest';
msg.headers = { 'content-type': 'application/json', 'x-internal-key': env.get('INTERNAL_API_KEY') };
return msg;

const ok = msg.statusCode === 200;
const p = msg.payload || {};
node.status(ok
  ? { fill: 'green', shape: 'dot', text: `${p.readerId}: ${p.accepted} nuevas · ${p.duplicates} duplicadas` }
  : { fill: 'red', shape: 'ring', text: `HTTP ${msg.statusCode}: ${p.message || 'error'}` });
return msg;

const readerId = (msg.topic || '').split('/')[2];
msg.method = 'POST';
msg.url = (env.get('RFID_SERVICE_URL') || 'http://rfid-service:3004') + `/internal/rfid/readers/${encodeURIComponent(readerId)}/heartbeat`;
msg.headers = { 'x-internal-key': env.get('INTERNAL_API_KEY') };
msg.payload = '';
return msg;
